local VERSION='9.0.0'
local reviews, evidence, trends = {}, {}, {}
local function uid(p)return('%s-%s-%04d'):format(p,os.time(),math.random(0,9999))end
exports('CreateMortalityReviewV9',function(caseId,data,reviewer)data=type(data)=='table'and data or{};local preventability=0;if data.delayedResponse then preventability=preventability+25 end;if data.missedCriticalResult then preventability=preventability+30 end;if data.protocolDeviation then preventability=preventability+25 end;if data.unavoidable then preventability=math.max(0,preventability-60)end;local item={id=uid('MORT'),caseId=caseId,reviewer=reviewer,preventability=math.min(100,preventability),classification=preventability>=50 and'potentially_preventable'or preventability>=20 and'possibly_preventable'or'not_preventable',data=data,createdAt=os.time()};reviews[item.id]=item;trends[item.classification]=(trends[item.classification]or 0)+1;return true,item end)
exports('LinkEvidenceChainV9',function(caseId,evidenceId,from,to,actor)local item={id=uid('EVID'),caseId=caseId,evidenceId=evidenceId,from=from,to=to,actor=actor,transferredAt=os.time()};evidence[item.id]=item;return true,item end)
exports('GetV9CoronerBoard',function()return{version=VERSION,reviews=reviews,evidence=evidence,trends=trends,generatedAt=os.time()}end)
CreateThread(function()Wait(5600);pcall(function()exports['dpn-medical-core']:RegisterModule('dpn-medical-coroner',VERSION,{'mortality_review','preventability_analysis','evidence_chain','mortality_trends'})end);print('[dpn-medical-coroner] v9 mortality review and evidence governance active')end)
